def weekly_pay(rate, hour):
    if hour > 30:
        return rate * 30 + 1.5 * rate * (hour - 30)
    return rate * hour
print(int(weekly_pay(11000, 32)))

def filter_odd(lst):
    odd = []
    for n in lst:
        if n % 2 != 0:
            odd.append(n)
    return odd
print(filter_odd([1, 2, 3, 4, 5]))

def factorial(n):
    r = 1
    for i in range(1, n + 1):
        r *= i
    return r
print(f"5! = {factorial(5)}")

def count_vowels(s):
    c = 0
    for ch in s.lower():
        if ch in "aeiou":
            c += 1
    return c
